mapper.select:
SELECT i.industry_name AS industryName, COALESCE(SUM(r.ent_count),0) AS count FROM sys_industry i LEFT JOIN stat_ent_rpt r ON i.industry_code = r.industry_code
r.deleted = 0
AND r.region_code IN (SELECT region_code FROM sys_area WHERE region_name LIKE CONCAT('%',#{req.regionName},'%'))
AND r.scale = #{req.scale}
AND i.industry_type = #{req.industryType}
GROUP BY i.industry_name

SELECT ent_name AS entName, scale, location FROM biz_ent_info WHERE deleted = 0
AND scale = #{req.scale}
ORDER BY id DESC LIMIT 20
